<?php declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/auth.php';require_customer();$config=require __DIR__.'/inc/xendit.php';$secret=(string)$config['secret_key'];$id=(int)($_GET['order_id']??0);$q=$pdo->prepare('SELECT a.*,h.id header_id,h.user_id,h.status header_status FROM ai_cake_orders a JOIN order_headers h ON h.ai_order_id=a.id WHERE a.id=? AND h.user_id=?');$q->execute([$id,user_id()]);$o=$q->fetch();if(!$o)exit('Order not found.');if($o['payment_status']==='paid')redirect('order_details.php?id='.$o['header_id']);if($o['payment']!=='gcash')exit('This is not a GCash order.');if((float)$o['total']<=0)exit('Staff must assign the AI cake price before payment.');if(!empty($o['payment_reference'])&&str_starts_with($o['payment_reference'],'http'))redirect($o['payment_reference']);$base=rtrim((string)env_value('APP_URL','http://localhost/AI-CAKE'),'/');$payload=['external_id'=>$o['order_number'],'amount'=>(float)$o['total'],'currency'=>'PHP','description'=>'AI cake order '.$o['order_number'],'payment_methods'=>['GCASH'],'success_redirect_url'=>$base.'/order_details.php?id='.$o['header_id'],'failure_redirect_url'=>$base.'/order_details.php?id='.$o['header_id']];$ch=curl_init('https://api.xendit.co/v2/invoices');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Basic '.base64_encode($secret.':')],CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true]);$raw=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$r=json_decode((string)$raw,true);if($http<200||$http>=300||empty($r['invoice_url'])||empty($r['id']))exit('Unable to create GCash invoice.');$pdo->beginTransaction();try{$pdo->prepare("UPDATE ai_cake_orders SET payment_reference=?,payment_invoice_id=?,payment_status='pending' WHERE id=?")->execute([$r['invoice_url'],$r['id'],$id]);$pdo->prepare("UPDATE order_headers SET payment_reference=?,payment_status='pending' WHERE id=?")->execute([$r['invoice_url'],$o['header_id']]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;}redirect($r['invoice_url']);
